// Shop abrufen (SHOPIFY 3, Migration 82): je verbundenem Shop Name, Währung, öffentliche Domain und Produkte (read_products) holen und prüfen, ob Verkaufszahlen
// abrufbar sind (ShopifyQL, read_reports). Läuft das Token bald ab, wird es vorher erneuert (Refresh-Token, Angaben nur aus shopify_zugang). Keine Bestellungen,
// keine Kundendaten. Ausgabe je Shop: daten (für shopify_shop_ergebnis) und neu (Antwort beim Erneuern, sonst leer). Keine Ausführungsdaten (Einstellung des Ablaufs).
const API = '2026-10';
const aus = [];
const formular = f => Object.keys(f || {}).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(String(f[k] ?? ''))).join('&');
const DOM = /^[a-z0-9][a-z0-9-]{0,59}\.myshopify\.com$/;
// Fix 22.10.: Antworten als Text, Buffer oder Objekt lesen; Texte zeichenweise kürzen und ohne einzelne Surrogate bzw. Nullzeichen (sonst lehnt Postgres das JSON ab)
const istBuf = x => typeof Buffer !== 'undefined' && Buffer.isBuffer(x);
const lies = b => { if (b && typeof b === 'object' && !istBuf(b)) return b; try { return JSON.parse(istBuf(b) ? b.toString('utf8') : String(b || '')); } catch (e) { return null; } };
const rein = (v, n) => Array.from(String(v ?? '').replace(/[\uD800-\uDFFF]/gu, '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, ' ')).slice(0, n).join('');
for (const it of $input.all()) {
  const z = (it.json || {}).z || {};
  const shopId = String(z.shop_id || (it.json || {}).shop_id || '');
  let neu = '';
  const fertig = d => aus.push({ json: { shop_id: shopId, daten: JSON.stringify(d), neu } });
  try {
    if (z.ok !== true) { fertig({ ok: false, fehler: String(z.fehler || 'Der Shop ist nicht verbunden.') }); continue; }
    if (!DOM.test(String(z.domain || ''))) { fertig({ ok: false, fehler: 'Ungültige Shop-Adresse.' }); continue; }
    let token = String(z.token || '');
    if (z.erneuern === true) {
      if (String(z.url || '') !== 'https://' + z.domain + '/admin/oauth/access_token') { fertig({ ok: false, fehler: 'Ungültige Adresse zum Erneuern.' }); continue; }
      const a = await this.helpers.httpRequest({ method: 'POST', url: z.url, body: formular(z.form), headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
        json: false, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
      const d = lies(a.body);
      if (a.statusCode !== 200 || !d || !d.access_token) { fertig({ ok: false, fehler: 'Der Zugang konnte nicht erneuert werden (' + a.statusCode + '). Die App muss in Shopify neu geöffnet bzw. installiert werden.' }); continue; }
      const keep = {}; for (const k of ['access_token', 'scope', 'expires_in', 'refresh_token', 'refresh_token_expires_in']) if (d[k] !== undefined) keep[k] = d[k];
      neu = JSON.stringify(keep); token = d.access_token;
    }
    const gql = async (query, variables) => {
      const a = await this.helpers.httpRequest({ method: 'POST', url: 'https://' + z.domain + '/admin/api/' + API + '/graphql.json', body: { query, variables: variables || {} },
        headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' }, json: true, timeout: 60000, returnFullResponse: true, ignoreHttpStatusErrors: true });
      if (a.statusCode === 401 || a.statusCode === 403) throw new Error('Shopify lehnt den Zugang ab (' + a.statusCode + '). Die App muss in Shopify neu installiert werden.');
      if (a.statusCode !== 200) throw new Error('Shopify antwortet mit Fehler ' + a.statusCode + '.');
      return lies(a.body) || {};
    };
    const s = await gql('{ shop { name currencyCode primaryDomain { host } } }');
    if (!s.data || !s.data.shop) throw new Error('Shopify hat keine Shop-Angaben geliefert' + (s.errors && s.errors[0] ? ': ' + String(s.errors[0].message).slice(0, 200) : '.'));
    const produkte = [];
    let nach = null;
    for (let seite = 0; seite < 20; seite++) {
      const p = await gql('query($c: String) { products(first: 100, after: $c, sortKey: TITLE) { pageInfo { hasNextPage endCursor } nodes { id title status variants(first: 100) { nodes { id title sku } } } } }', { c: nach });
      if (!p.data || !p.data.products) throw new Error('Die Produkte konnten nicht geladen werden' + (p.errors && p.errors[0] ? ': ' + String(p.errors[0].message).slice(0, 200) : '.'));
      for (const n of p.data.products.nodes || []) {
        const id = String(n.id || '').split('/').pop();
        if (!/^[0-9]{1,18}$/.test(id)) continue;
        produkte.push({ id, titel: rein(n.title, 300), status: rein(n.status, 30),
          varianten: ((n.variants || {}).nodes || []).map(v => ({ id: String(v.id || '').split('/').pop(), titel: rein(v.title, 200), sku: rein(v.sku, 100) })) });
      }
      if (!p.data.products.pageInfo || !p.data.products.pageInfo.hasNextPage) break;
      nach = p.data.products.pageInfo.endCursor;
    }
    // Verkaufszahlen abrufbar? (nur Summe des letzten Tages, ohne Speicherung)
    let reportsOk = true, reportsFehler = '';
    try {
      const r = await gql('{ shopifyqlQuery(query: "FROM sales SHOW net_sales SINCE -1d UNTIL today") { parseErrors tableData { columns { name } } } }');
      if (r.errors && r.errors.length) { reportsOk = false; reportsFehler = rein(r.errors[0].message, 200); }
      else if (r.data && r.data.shopifyqlQuery && (r.data.shopifyqlQuery.parseErrors || []).length) { reportsOk = false; reportsFehler = rein(JSON.stringify(r.data.shopifyqlQuery.parseErrors[0]), 200); }
    } catch (e) { reportsOk = false; reportsFehler = rein(e.message || e, 200); }
    fertig({ ok: true, shop_name: rein(s.data.shop.name, 200), waehrung: String(s.data.shop.currencyCode || ''),
      domain_oeffentlich: String(((s.data.shop.primaryDomain || {}).host) || '').toLowerCase(), produkte, reports_ok: reportsOk, reports_fehler: reportsFehler });
  } catch (e) {
    fertig({ ok: false, fehler: rein(e.message || e, 400) });
  }
}
return aus;

// Prüf-Aufträge (SHOPIFY 3, Migration 98): je abgelegter Datei eines Verkaufsberichts ein Auftrag „pruefen“ an SPEICHER 1 (Bereich ally, nur lesen).
// Die Pfade kommen aus shopify_auftraege (gespeichert beim Ablegen); höchstens 20 je Lauf. Ergebnis: shopify_ablage_stand.
const raus = [];
for (const it of $input.all()) {
  const a = (it.json || {}).a || {};
  const p = String(a.pfad || '');
  if (a.typ !== 'ablage' || !p || p.length > 1000 || p.startsWith('/') || /[\u0000-\u001f]/.test(p)) continue;
  raus.push({ json: { aktion: 'pruefen', bereich: 'ally', pfad: p } });
  if (raus.length >= 20) break;
}
return raus;

// Ergebnisse sammeln (SHOPIFY 3, Migration 98): Antworten von SPEICHER 1 (nur aktion, pfad, ok, vorhanden) als eine Liste für shopify_ablage_stand.
// Fehlerhafte oder unklare Antworten ändern in der Datenbank nichts.
const e = $input.all().map(it => it.json || {}).filter(j => j.aktion === 'pruefen' && typeof j.pfad === 'string')
  .map(j => ({ ok: j.ok === true, aktion: 'pruefen', bereich: String(j.bereich || 'ally'), pfad: j.pfad.slice(0, 1000), vorhanden: j.vorhanden === true ? true : j.vorhanden === false ? false : null }));
return [{ json: { e: JSON.stringify(e) } }];
